      throw new Error('cursor must be a string');
    }
    const decoded = decodeCursor(args.cursor);
    if (decoded === null) {
      throw new Error('Invalid cursor');
    }
    startIndex = decoded;
  }

  // Get page of events
  const page = events.slice(startIndex, startIndex + pageSize);
  const hasMore = startIndex + pageSize < events.length;

  // Build response
  const lines = page.map(e => `- ${e.id}: ${e.name}`);
  let text = lines.join('\n');

  if (hasMore) {
    const nextCursor = encodeCursor(startIndex + pageSize);
    text += `\nnext_cursor: ${nextCursor}`;
